  const c = cps[i++]
  if (c === '\n') { line++; col = 1 }
  else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
  else col++
  return c
}
const fail = (l, c, r) => { throw new Fail(`error: ${l}:${c}: ${r}`) }

function digits(pred) {
  // consume a run of digits with single underscores between digits; returns count
  let count = 0
  while (i < n) {
    if (pred(cps[i])) { adv(); count++ }
    else if (cps[i] === '_' && count > 0 && pred(cps[i - 1]) && pred(cps[i + 1])) adv()
    else break
  }
  return count
}

