  const start = i
  const sl = line, sc = col
  let ok = true
  if (cps[i] === '0' && 'xXbBoO'.includes(cps[i + 1] ?? '#')) {
    const p = cps[i + 1].toLowerCase()
    adv(); adv()
    ok = digits(p === 'x' ? isHex : p === 'b' ? isBin : isOct) > 0
  } else {
    digits(isDigit)
    if (cps[i] === '.' && isDigit(cps[i + 1])) { adv(); digits(isDigit) }
    if (cps[i] === 'e' || cps[i] === 'E') {
      const a = cps[i + 1], b = cps[i + 2]
      if (isDigit(a) || ((a === '+' || a === '-') && isDigit(b))) { adv(); if (!isDigit(cps[i])) adv(); digits(isDigit) }
    }
