  const sl = line, sc = col
  adv()
  let out = ''
  for (;;) {
    if (i >= n) fail(sl, sc, 'unterminated string')
    const c = cps[i]
    if (c === '"') { adv(); break }
    if (c === '\n') fail(line, col, 'newline in string')
    if (c !== '\\') { out += adv(); continue }
    const el = line, ec = col
    adv()
    if (i >= n) fail(sl, sc, 'unterminated string')
    const e = cps[i]
    const bad = () => fail(el, ec, `invalid escape \\${e}`)
