      let j = i + 2, h = ''
      while (isHex(cps[j])) h += cps[j++]
      if (h === '' || cps[j] !== '}' || parseInt(h, 16) > 0x10ffff) bad()
      while (i <= j) adv()
      out += String.fromCodePoint(parseInt(h, 16))
    } else bad()
  }
  return { l: sl, c: sc, kind: 'string', body: JSON.stringify(out) }
