function scan() {
  const toks = []
  while (i < n) {
    const c = cps[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && cps[i + 1] === '/') { while (i < n && cps[i] !== '\n') adv(); continue }
    if (c === '/' && cps[i + 1] === '*') {
      const sl = line, sc = col
      adv(); adv()
      let depth = 1
      while (depth > 0) {
        if (i >= n) fail(sl, sc, 'unterminated block comment')
        if (cps[i] === '*' && cps[i + 1] === '/') { adv(); adv(); depth-- }
        else if (cps[i] === '/' && cps[i + 1] === '*') { adv(); adv(); depth++ }
        else adv()
      }
      continue
    }
    if (c === 'r' && cps[i + 1] === '"') {
      const sl = line, sc = col
      adv(); adv()
      let s = ''
      while (i < n && cps[i] !== '"') s += adv()
      if (i >= n) fail(sl, sc, 'unterminated string')
      adv()
      toks.push({ l: sl, c: sc, kind: 'rawstring', body: JSON.stringify(s) })
      continue
    }
    if (isIdStart(c)) {
      const sl = line, sc = col, st = i
      while (isIdCont(cps[i])) adv()
      const t = cps.slice(st, i).join('')
