    if (c === '"') { toks.push(string()); continue }
    const two = c + (cps[i + 1] ?? '')
    if (PUNCT2.has(two)) {
      const sl = line, sc = col
      adv(); adv()
      toks.push({ l: sl, c: sc, kind: 'punct', body: two })
      continue
    }
    if (PUNCT1.has(c)) {
      const sl = line, sc = col
      adv()
      toks.push({ l: sl, c: sc, kind: 'punct', body: c })
      continue
    }
    fail(line, col, `unexpected character ${c}`)
  }
